      if (!resolution) return false;
      var parts = resolution.split('x');
      if (parts.length !== 2) return false;
      var width = parseFloat(parts[0]);
      var height = parseFloat(parts[1]);
      if (width > 0 && height > 0) {
        this.timesX = width / w;
        this.timesY = height / h;
        console.log('分辨率:', resolution);
        console.log('倍率计算: timesX=', this.timesX, 'timesY=', this.timesY);
        return true;
      }
      return false;
