    getArrowPositions(p1, p2) {
      const dx = p2.x - p1.x;
      const dy = p2.y - p1.y;
      const len = Math.sqrt(dx * dx + dy * dy);
      if (len === 0) return null;
      const ux = dx / len;
      const uy = dy / len;
      const perpLen = 40;
      const mx = (p1.x + p2.x) / 2;
      const my = (p1.y + p2.y) / 2;
      const arrow1X = mx + uy * perpLen;
      const arrow1Y = my - ux * perpLen;
      const arrow2X = mx - uy * perpLen;
      const arrow2Y = my + ux * perpLen;
      return {
        arrow1: { x: Number(arrow1X.toFixed(2)), y: Number(arrow1Y.toFixed(2)) },
        arrow2: { x: Number(arrow2X.toFixed(2)), y: Number(arrow2Y.toFixed(2)) }
      };
    },

    // ==================== 修改后的 initCanvas4（支持多折线点，双击后锁定） ====================
    initCanvas4() {
      this.$nextTick(() => {
        const cav = this.$refs.mycanvas;
        if (!cav) return;
        
        cav.width = 640;
        cav.height = 360;
        cav.style.cursor = "crosshair";
        
        if (!this.imgOpen) {
          console.log('图片未加载完成，等待...');
          return;
        }
        
        let isDrawing = false;
        let tempStart = null;
        let currentPoints = [];
        let isHoveringLine = false;
        let isCompleted = this.isPolylineCompleted || false;
        
        const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
        const clampX = (x) => clamp(Math.round(x), 0, 640);
        const clampY = (y) => clamp(Math.round(y), 0, 360);
        
        const drawAllBoxes = (ctx) => {
          this.mark_list.forEach(polygon => {
            if (polygon.length < 3) return;
            ctx.beginPath();
            ctx.strokeStyle = polygon[0].color || '#f00';
            ctx.lineWidth = 2;
            ctx.moveTo(clampX(polygon[0].x), clampY(polygon[0].y));
            polygon.forEach(point => ctx.lineTo(clampX(point.x), clampY(point.y)));
            ctx.closePath();
            ctx.stroke();
          });
        };
        
        const drawPolyline = (ctx, points, isTemporary = false, highlight = false) => {
          if (points.length < 2) return;
          ctx.save();
          ctx.strokeStyle = isTemporary ? 'rgba(255, 215, 0, 0.5)' : (highlight ? '#ff6b6b' : "#ffd700");
          ctx.lineWidth = highlight ? 4 : 2;
          ctx.setLineDash(isTemporary ? [5, 5] : []);
          ctx.beginPath();
          ctx.moveTo(clampX(points[0].x), clampY(points[0].y));
          for (let i = 1; i < points.length; i++) {
            ctx.lineTo(clampX(points[i].x), clampY(points[i].y));
          }
          ctx.stroke();
          ctx.setLineDash([]);
          if (!isCompleted) {
            points.forEach((p, index) => {
              ctx.beginPath();
              ctx.arc(clampX(p.x), clampY(p.y), 4, 0, 2 * Math.PI);
              ctx.fillStyle = isTemporary ? 'rgba(255, 215, 0, 0.5)' : '#ffd700';
              ctx.fill();
              ctx.strokeStyle = '#fff';
              ctx.lineWidth = 1;
              ctx.stroke();
              ctx.fillStyle = '#fff';
              ctx.font = '10px Arial';
              ctx.textAlign = 'center';
              ctx.fillText(index + 1, clampX(p.x), clampY(p.y) - 8);
            });
          } else {
            points.forEach((p) => {
              ctx.beginPath();
              ctx.arc(clampX(p.x), clampY(p.y), 3, 0, 2 * Math.PI);
              ctx.fillStyle = '#ffd700';
              ctx.fill();
            });
          }
          ctx.restore();
        };
        
        const drawArrowOnPolyline = (ctx, points, direction) => {
          if (points.length < 2) return;
          let totalLen = 0;
          let segmentLengths = [];
          for (let i = 1; i < points.length; i++) {
            const segDx = points[i].x - points[i-1].x;
            const segDy = points[i].y - points[i-1].y;
            const segLen = Math.sqrt(segDx * segDx + segDy * segDy);
            segmentLengths.push(segLen);
            totalLen += segLen;
          }
          let halfLen = totalLen / 2;
          let accumulated = 0;
          let midIndex = 0;
          let midT = 0;
          for (let i = 0; i < segmentLengths.length; i++) {
            if (accumulated + segmentLengths[i] >= halfLen) {
              midIndex = i;
              midT = (halfLen - accumulated) / segmentLengths[i];
              break;
            }
            accumulated += segmentLengths[i];
          }
          midIndex = Math.min(midIndex, points.length - 2);
          const pA = points[midIndex];
          const pB = points[midIndex + 1];
          const mx = pA.x + (pB.x - pA.x) * midT;
          const my = pA.y + (pB.y - pA.y) * midT;
          const segDx = pB.x - pA.x;
          const segDy = pB.y - pA.y;
          const segLen = Math.sqrt(segDx * segDx + segDy * segDy);
          if (segLen === 0) return;
          const segUx = segDx / segLen;
          const segUy = segDy / segLen;
          const arrowLen = 40;
          let arrow1X = mx + segUy * arrowLen;
          let arrow1Y = my - segUx * arrowLen;
          let arrow2X = mx - segUy * arrowLen;
          let arrow2Y = my + segUx * arrowLen;
          arrow1X = clamp(arrow1X, 15, 625);
          arrow1Y = clamp(arrow1Y, 15, 345);
          arrow2X = clamp(arrow2X, 15, 625);
          arrow2Y = clamp(arrow2Y, 15, 345);
          
          const drawArrow = (fromX, fromY, toX, toY, color, text) => {
            ctx.save();
            ctx.strokeStyle = color;
            ctx.fillStyle = color;
            ctx.lineWidth = 2;
            const headLen = 8;
            const angle = Math.atan2(toY - fromY, toX - fromX);
            ctx.beginPath();
            ctx.moveTo(fromX, fromY);
            ctx.lineTo(toX, toY);
            ctx.stroke();
            ctx.beginPath();
            const arrowX1 = toX - headLen * Math.cos(angle - Math.PI / 6);
            const arrowY1 = toY - headLen * Math.sin(angle - Math.PI / 6);
            const arrowX2 = toX - headLen * Math.cos(angle + Math.PI / 6);
            const arrowY2 = toY - headLen * Math.sin(angle + Math.PI / 6);
            ctx.moveTo(toX, toY);
            ctx.lineTo(arrowX1, arrowY1);
            ctx.lineTo(arrowX2, arrowY2);
            ctx.fill();
            ctx.font = "bold 14px Arial";
            ctx.textAlign = "center";
            let textY = toY - 10;
            textY = clamp(textY, 12, 352);
            ctx.fillStyle = color;
            ctx.fillText(text, toX, textY);
            ctx.restore();
          };
          
          if (direction === 'left') {
            drawArrow(mx, my, arrow1X, arrow1Y, '#44ff44', 'IN');
            drawArrow(mx, my, arrow2X, arrow2Y, '#ff4444', 'OUT');
          } else {
            drawArrow(mx, my, arrow2X, arrow2Y, '#44ff44', 'IN');
            drawArrow(mx, my, arrow1X, arrow1Y, '#ff4444', 'OUT');
          }
        };
        
        const renderAll = () => {
          const ctx = cav.getContext("2d");
          ctx.clearRect(0, 0, cav.width, cav.height);
          drawAllBoxes(ctx);
          if (this.polylinePoints.length >= 2) {
            drawPolyline(ctx, this.polylinePoints, false, isHoveringLine);
            drawArrowOnPolyline(ctx, this.polylinePoints, this.lineDirection);
          }
          if (isDrawing && tempStart && currentPoints.length > 0 && !isCompleted) {
            const tempPoints = [...currentPoints, tempStart];
            drawPolyline(ctx, tempPoints, true);
          }
        };
        
        cav.onmousedown = (e) => {
          const rect = cav.getBoundingClientRect();
          const scaleX = cav.width / rect.width;
          const scaleY = cav.height / rect.height;
          let x = (e.clientX - rect.left) * scaleX;
          let y = (e.clientY - rect.top) * scaleY;
          x = clampX(x);
          y = clampY(y);
          
          if (isCompleted && this.polylinePoints.length >= 2) {
            let isNearLine = false;
            for (let i = 1; i < this.polylinePoints.length; i++) {
              const p1 = this.polylinePoints[i-1];
              const p2 = this.polylinePoints[i];
              const dist = this.distanceToSegment(x, y, p1.x, p1.y, p2.x, p2.y);
              if (dist < 15) { isNearLine = true; break; }
            }
            if (isNearLine) {
              this.lineDirection = this.lineDirection === 'left' ? 'right' : 'left';
              console.log('切换方向:', this.lineDirection);
              this.updateCrossLineData();
              renderAll();
              this.$message.success(`方向已切换为: ${this.lineDirection === 'left' ? 'IN左 OUT右' : 'IN右 OUT左'}`);
            }
            return;
          }
          if (isCompleted) return;
          
          if (this.polylinePoints.length >= 2) {
            let isNearLine = false;
            for (let i = 1; i < this.polylinePoints.length; i++) {
              const p1 = this.polylinePoints[i-1];
              const p2 = this.polylinePoints[i];
              const dist = this.distanceToSegment(x, y, p1.x, p1.y, p2.x, p2.y);
              if (dist < 15) { isNearLine = true; break; }
            }
            if (isNearLine) {
              this.lineDirection = this.lineDirection === 'left' ? 'right' : 'left';
              console.log('切换方向:', this.lineDirection);
              this.updateCrossLineData();
              renderAll();
              this.$message.success(`方向已切换为: ${this.lineDirection === 'left' ? 'IN左 OUT右' : 'IN右 OUT左'}`);
              return;
            }
          }
          
          if (!this.isDrawingPolyline) {
            this.isDrawingPolyline = true;
            if (this.polylinePoints.length === 0) {
              currentPoints = [];
              this.polylinePoints = [];
            } else {
              currentPoints = [...this.polylinePoints];
            }
          }
          const newPoint = { x: x, y: y };
          currentPoints.push(newPoint);
          this.currentDrawingPoints = [...currentPoints];
          this.polylinePoints = [...currentPoints];
          if (this.polylinePoints.length >= 2) {
            this.updateCrossLineData();
          }
          isDrawing = true;
          tempStart = { x: x, y: y };
          renderAll();
        };
        
        cav.onmousemove = (e) => {
          const rect = cav.getBoundingClientRect();
          const scaleX = cav.width / rect.width;
          const scaleY = cav.height / rect.height;
          let x = (e.clientX - rect.left) * scaleX;
          let y = (e.clientY - rect.top) * scaleY;
          x = clampX(x);
          y = clampY(y);
          
          if (this.polylinePoints.length >= 2) {
            let nearLine = false;
            for (let i = 1; i < this.polylinePoints.length; i++) {
              const p1 = this.polylinePoints[i-1];
              const p2 = this.polylinePoints[i];
              const dist = this.distanceToSegment(x, y, p1.x, p1.y, p2.x, p2.y);
              if (dist < 15) { nearLine = true; break; }
            }
            if (nearLine !== isHoveringLine) {
              isHoveringLine = nearLine;
              cav.style.cursor = nearLine ? 'pointer' : 'crosshair';
              renderAll();
            }
          }
          if (this.isDrawingPolyline && currentPoints.length > 0 && !isCompleted) {
            tempStart = { x: x, y: y };
            renderAll();
          }
        };
        
        cav.onmouseleave = () => {
          isHoveringLine = false;
          cav.style.cursor = 'crosshair';
        };
        
        cav.onmouseenter = () => {
          if (this.isDrawingPolyline && currentPoints.length > 0 && !isCompleted) {
            renderAll();
          }
        };
        
        cav.ondblclick = (e) => {
          if (this.polylinePoints.length >= 2 && !isCompleted) {
            isCompleted = true;
            this.isPolylineCompleted = true;
            this.isDrawingPolyline = false;
            currentPoints = [];
            this.currentDrawingPoints = [];
            this.updateCrossLineData();
            cav.style.cursor = 'pointer';
            this.$message.success("折线绘制完成，点击线条切换IN/OUT方向");
            renderAll();
          } else if (isCompleted) {
            this.$message.info("折线已锁定，点击线条切换IN/OUT方向");
          }
        };
        
        cav.oncontextmenu = (e) => {
          e.preventDefault();
          if (!isCompleted && this.isDrawingPolyline) {
            this.isDrawingPolyline = false;
            currentPoints = [];
            this.currentDrawingPoints = [];
            this.polylinePoints = [];
            this.form.cross_line = {};
            isCompleted = false;
            this.isPolylineCompleted = false;
            renderAll();
            this.$message.info("已取消绘制");
          }
        };
        
        renderAll();
      });
    },

